from collections import deque


def _is_atom(atom, pred, args):
    if atom[0] != pred:
        return False
    if len(atom) - 1 != len(args):
        return False
    return tuple(atom[1:]) == tuple(args)


def _find_atom(state, pred, args):
    for atom in state:
        if _is_atom(atom, pred, args):
            return atom
    return None


def _apply_negative(state, pred, args):
    target = (pred,) + tuple(args)
    return {a for a in state if a != target}


def _apply_positive(state, pred, args):
    state = _apply_negative(state, pred, args)
    state.add((pred,) + tuple(args))
    return state


def _ground_walk(state, objects):
    mans = [o for o, t in objects if t == "man"]
    locs = [o for o, t in objects if t == "location"]
    actions = []
    for m in mans:
        for s in locs:
            if _find_atom(state, "at", (m, s)) is None:
                continue
            for e in locs:
                if e == s:
                    continue
                if _find_atom(state, "link", (s, e)) is not None:
                    actions.append(("walk", s, e, m))
    return actions


def _ground_pickup(state, objects):
    mans = [o for o, t in objects if t == "man"]
    locs = [o for o, t in objects if t == "location"]
    spans = [o for o, t in objects if t == "spanner"]
    actions = []
    for m in mans:
        for l in locs:
            if _find_atom(state, "at", (m, l)) is None:
                continue
            for s in spans:
                if _find_atom(state, "at", (s, l)) is not None:
                    actions.append(("pickup_spanner", l, s, m))
    return actions


def _ground_tighten(state, objects):
    mans = [o for o, t in objects if t == "man"]
    locs = [o for o, t in objects if t == "location"]
    spans = [o for o, t in objects if t == "spanner"]
    nuts = [o for o, t in objects if t == "nut"]
    actions = []
    for m in mans:
        for l in locs:
            if _find_atom(state, "at", (m, l)) is None:
                continue
            for s in spans:
                if _find_atom(state, "carrying", (m, s)) is None:
                    continue
                if _find_atom(state, "useable", (s,)) is None:
                    continue
                for n in nuts:
                    if _find_atom(state, "at", (n, l)) is not None:
                        if _find_atom(state, "loose", (n,)) is not None:
                            actions.append(("tighten_nut", l, s, m, n))
    return actions


def _apply(state, action):
    name = action[0]
    if name == "walk":
        _, s, e, m = action
        state = _apply_negative(state, "at", (m, s))
        state = _apply_positive(state, "at", (m, e))
        return state
    if name == "pickup_spanner":
        _, l, s, m = action
        state = _apply_negative(state, "at", (s, l))
        state = _apply_positive(state, "carrying", (m, s))
        return state
    if name == "tighten_nut":
        _, l, s, m, n = action
        state = _apply_negative(state, "loose", (n,))
        state = _apply_negative(state, "useable", (s,))
        state = _apply_positive(state, "tightened", (n,))
        return state
    return state


def _grounded_actions(state, objects):
    return _ground_walk(state, objects) + _ground_pickup(state, objects) + _ground_tighten(state, objects)


def _goal_satisfied(state, goal):
    for g in goal:
        if g not in state:
            return False
    return True


def _plan_to_str(action):
    parts = [action[0]] + [str(a) for a in action[1:]]
    return "(" + " ".join(parts) + ")"


def get_plan(objects, init, goal):
    init_state = set(init)
    initial_actions = _grounded_actions(init_state, objects)
    order = []
    order.extend(a for a in initial_actions if a[0] == "tighten_nut")
    order.extend(a for a in initial_actions if a[0] == "pickup_spanner")
    order.extend(a for a in initial_actions if a[0] == "walk")

    visited = set()
    visited.add(frozenset(init_state))

    def hash_state(state):
